class AsyncPreviewsGroup:
    """Asynchronous operations of the *Previews* group."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._t = transport

    async def get_previews_that_are_processing(
        self,
        *,
        cursor_preview_file_id: Optional[str] = None,
        limit: Optional[int] = None,
    ) -> list[GetPreviewsThatAreProcessingItem]:
        """Get the previews that are processing.

        Get the preview files of the open projects that have the processing or broken
        status. To get the next page, give the identifier of the last preview in
        cursor_preview_file_id. You must be an administrator.

        Args:
            cursor_preview_file_id: Get the previews that come after this preview
            limit: Maximum number of previews

        ``GET /data/playlists/preview-files/running``
        """
        return await self._t.request(
            "GET",
            "/data/playlists/preview-files/running",
            params={"cursor_preview_file_id": cursor_preview_file_id, "limit": limit},
            response_type=list[GetPreviewsThatAreProcessingItem],
        )

    async def upload_file_of_preview(
        self,
        instance_id: str,
        *,
        file: FileInput,
        normalize: Optional[bool] = None,
        no_job: Optional[bool] = None,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> UploadFileOfPreviewResponse:
        """Upload the file of a preview.

        Upload the file of a preview. Send the file in a multipart form. For a picture,
        the route makes a square thumbnail, a rectangle thumbnail and a preview picture.
        For a movie, the route normalizes the movie and makes the thumbnails. Use
        normalize=false to keep the movie as it is. You cannot upload a file again for a
        preview that already has a file. You must be able to do actions on the task. A
        client of the project cannot use this route.

        Args:
            instance_id: Unique identifier of the preview file
            normalize: Normalize the movie
            no_job: Process the file in the request instead of the job queue
            file: Preview file to upload

        ``POST /pictures/preview-files/{instance_id}``
        """
        return await self._t.request(
            "POST",
            "/pictures/preview-files/{instance_id}",
            path_params={"instance_id": instance_id},
            params={"normalize": normalize, "no_job": no_job},
            body={},
            extra_body=extra_body,
            files={"file": file},
            body_mode="multipart",
            response_type=UploadFileOfPreviewResponse,
        )

